    'no AI client directory found; use --dir') printf '%s' '没找到 AI 客户端目录；用 --dir 指定' ;;
    'removed the skill from') printf '%s' '已从下列目录移除 skill' ;;
    'this copy has no skill package') printf '%s' '这份副本里没有 skill 包' ;;
    'only one action is allowed') printf '%s' '只允许一个动作' ;;
    'only one client is allowed') printf '%s' '只允许一个客户端' ;;
    'installing') printf '%s' '正在安装' ;;
    'try a writable prefix') printf '%s' '换一个可写的前缀' ;;
    'recovering the installed copy after an interrupted swap') printf '%s' '正在从被打断的切换中恢复已安装的副本' ;;
    'failed to write the install manifest') printf '%s' '写入安装清单失败' ;;
    'failed to create symlink') printf '%s' '创建符号链接失败' ;;
    'no install manifest under') printf '%s' '这里没有安装清单：' ;;
    'nothing was removed, delete that directory by hand if you are sure') printf '%s' '没有删除任何东西；确认无误请手工删除该目录' ;;
    'removing') printf '%s' '正在删除：' ;;
    'failed to remove') printf '%s' '删除失败：' ;;
    'leftover files were kept') printf '%s' '保留了未清理的文件：' ;;
    'left the symlink alone, it points elsewhere') printf '%s' '未动该符号链接，它指向别处：' ;;
    'left the file alone, it is not a symlink') printf '%s' '未动该文件，它不是符号链接：' ;;
    'removed') printf '%s' '已删除：' ;;
    'files') printf '%s' '个文件' ;;
    'no such file') printf '%s' '文件不存在：' ;;
    'checking for a newer version') printf '%s' '正在检查新版本' ;;
    'cannot read the latest version from the release API') printf '%s' '无法从 release API 读出最新版本' ;;
    'current version') printf '%s' '当前版本：' ;;
    'latest version') printf '%s' '最新版本：' ;;
    'no checksum for this release') printf '%s' '该版本没有校验和：' ;;
    'no checksum provided, skipping verification') printf '%s' '没有提供校验和，跳过校验：' ;;
    'cannot extract archive') printf '%s' '无法解包：' ;;
    'not a shellkit release') printf '%s' '这不是 shellkit 的发布包：' ;;
    'cannot read the version of') printf '%s' '无法读取版本号：' ;;
    'shellkit is not installed under') printf '%s' 'shellkit 没有装在：' ;;
    'run install-self first, or point --prefix at the right place') printf '%s' '先跑 install-self，或把 --prefix 指到正确位置' ;;
    'updating') printf '%s' '正在更新：' ;;
    'update failed') printf '%s' '更新失败：' ;;
    'running') printf '%s' '正在执行' ;;
    'target') printf '%s' '目标' ;;
    'force flag is set') printf '%s' '已开启强制模式' ;;
    'finished') printf '%s' '完成' ;;
    *) return 1 ;;
  esac
}
